<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop</title>
<style>
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { width: 100%; height: 100%; overflow: hidden; font-family: 'Ubuntu', 'Segoe UI', sans-serif; background: #0d0d0d; }
#desktop {
  width: 100%; height: 100%; position: relative;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
}
#taskbar {
  position: fixed; bottom: 0; left: 0; right: 0; height: 40px;
  background: rgba(0,0,0,0.85); backdrop-filter: blur(10px);
  display: flex; align-items: center; padding: 0 12px; gap: 8px;
  z-index: 1000; border-top: 1px solid rgba(255,255,255,0.08);
}
#taskbar button {
  background: #333; color: #eee; border: none; padding: 6px 16px;
  border-radius: 4px; cursor: pointer; font-size: 13px; transition: background 0.2s;
}
#taskbar button:hover { background: #e95420; }
#taskbar button:active { background: #c44a1a; }
.window {
  position: absolute; min-width: 360px; min-height: 240px;
  width: 420px; height: 320px; background: #2d2d2d;
  border-radius: 8px; box-shadow: 0 8px 32px rgba(0,0,0,0.6);
  color: #eee; display: flex; flex-direction: column; overflow: hidden;
  resize: both; z-index: 100;
}
#files-window { left: 50px; top: 50px; }
#notepad-window { left: 500px; top: 50px; }
.window-header {
  display: flex; justify-content: space-between; align-items: center;
  padding: 6px 10px; background: #3c3c3c; cursor: move; user-select: none; flex-shrink: 0;
}
.window-header span { font-size: 13px; font-weight: 500; }
.win-close {
  background: none; border: none; color: #ccc; cursor: pointer;
  font-size: 16px; line-height: 1; padding: 0 4px; border-radius: 3px;
}
.win-close:hover { background: #e95420; color: #fff; }
.window-body { flex: 1; padding: 8px; overflow: auto; display: flex; flex-direction: column; }
#files-path {
  font-family: monospace; font-size: 13px; color: #aaa; margin-bottom: 6px;
  padding: 4px 8px; background: #222; border-radius: 4px;
}
#files-up {
  align-self: flex-start; margin-bottom: 6px; background: #444; color: #eee;
  border: none; padding: 4px 12px; border-radius: 4px; cursor: pointer;
}
#files-up:hover { background: #555; }
#files-list { flex: 1; overflow-y: auto; }
.fs-item {
  padding: 6px 10px; cursor: pointer; border-radius: 4px; font-size: 13px;
}
.fs-item:hover { background: #3e3e3e; }
.fs-item.folder { color: #ffcc00; }
.fs-item.file { color: #ccc; }
.fs-item.folder::before { content: '📁 '; }
.fs-item.file::before { content: '📄 '; }
#tabs {
  display: flex; gap: 2px; background: #3c3c3c; padding: 4px 4px 0; flex-shrink: 0;
}
.tab {
  background: #555; color: #eee; border: none; padding: 4px 12px;
  border-radius: 4px 4px 0 0; cursor: pointer; font-size: 12px; transition: background 0.2s;
}
.tab.active { background: #2d2d2d; color: #fff; }
#new-tab {
  background: #333; color: #ccc; border: none; padding: 4px 8px;
  cursor: pointer; border-radius: 4px 4px 0 0; font-size: 14px;
}
#new-tab:hover { background: #444; }
#editor {
  flex: 1; background: #1e1e1e; color: #d4d4d4; border: none;
  border-top: 1px solid #444; resize: none; padding: 8px;
  font-family: 'Consolas', 'Monaco', monospace; font-size: 13px; outline: none;
}
</style>
</head>
<body>
<div id="desktop">
  <div id="taskbar">
    <button id="open-files">Files</button>
    <button id="open-notepad">Notepad</button>
  </div>

  <div id="files-window" class="window" style="display:none;">
    <div class="window-header">
      <span>Files</span>
      <button class="win-close">✕</button>
    </div>
    <div class="window-body">
      <div id="files-path">/</div>
      <button id="files-up">Up</button>
      <div id="files-list"></div>
    </div>
  </div>

  <div id="notepad-window" class="window" style="display:none;">
    <div class="window-header">
      <span>Notepad</span>
      <button class="win-close">✕</button>
    </div>
    <div class="window-body">
      <div id="tabs">
        <button id="new-tab">+ New</button>
      </div>
      <textarea id="editor"></textarea>
    </div>
  </div>
</div>

<script>
(function() {
  /* ---------- Filesystem data ---------- */
  const filesystem = {
    '/': ['bin', 'etc', 'home', 'usr', 'var'],
    '/bin': ['bash', 'ls', 'cat'],
    '/etc': ['hostname', 'fstab'],
    '/home': ['user'],
    '/home/user': ['Documents', 'Downloads', 'Pictures', 'notes.txt'],
    '/home/user/Documents': ['report.doc', 'todo.txt'],
    '/home/user/Downloads': ['file.zip'],
    '/home/user/Pictures': ['photo.jpg'],
    '/usr': ['bin', 'lib'],
    '/var': ['log']
  };

  function isDir(path) {
    return Object.prototype.hasOwnProperty.call(filesystem, path);
  }

  function getChildren(path) {
    return filesystem[path] || [];
  }

  /* ---------- Files app ---------- */
  let currentPath = '/';

  function renderFiles() {
    const pathEl = document.getElementById('files-path');
    const listEl = document.getElementById('files-list');
    pathEl.textContent = currentPath;
    listEl.innerHTML = '';
    const children = getChildren(currentPath);
    children.forEach(name => {
      const fullPath = currentPath === '/' ? '/' + name : currentPath + '/' + name;
      const item = document.createElement('div');
      item.className = 'fs-item' + (isDir(fullPath) ? ' folder' : ' file');
      item.textContent = name;
      item.addEventListener('dblclick', () => {
        if (isDir(fullPath)) {
          currentPath = fullPath;
          renderFiles();
        }
      });
      listEl.appendChild(item);
    });
  }

  document.getElementById('files-up').addEventListener('click', () => {
    if (currentPath === '/') return;
    const parts = currentPath.split('/').filter(p => p !== '');
    parts.pop();
    currentPath = parts.length === 0 ? '/' : '/' + parts.join('/');
    renderFiles();
  });

  /* ---------- Window management ---------- */
  function bringToFront(win) {
    const wins = document.querySelectorAll('.window');
    let maxZ = 100;
    wins.forEach(w => {
      const z = parseInt(w.style.zIndex || 0, 10);
      if (z > maxZ) maxZ = z;
    });
    win.style.zIndex = maxZ + 1;
  }

  function showWindow(id) {
    const win = document.getElementById(id);
    win.style.display = 'flex';
    bringToFront(win);
  }

  document.getElementById('open-files').addEventListener('click', () => {
    showWindow('files-window');
    renderFiles();
  });

  document.getElementById('open-notepad').addEventListener('click', () => {
    showWindow('notepad-window');
  });

  document.querySelectorAll('.win-close').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const win = e.target.closest('.window');
      win.style.display = 'none';
    });
  });

  /* ---------- Draggable windows ---------- */
  document.querySelectorAll('.window').forEach(win => {
    const header = win.querySelector('.window-header');
    let dragging = false;
    let startX = 0, startY = 0, origLeft = 0, origTop = 0;

    header.addEventListener('mousedown', (e) => {
      if (e.target.classList.contains('win-close')) return;
      dragging = true;
      startX = e.clientX;
      startY = e.clientY;
      origLeft = win.offsetLeft;
      origTop = win.offsetTop;
      bringToFront(win);
      e.preventDefault();
    });

    document.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      win.style.left = (origLeft + e.clientX - startX) + 'px';
      win.style.top = (origTop + e.clientY - startY) + 'px';
    });

    document.addEventListener('mouseup', () => {
      dragging = false;
    });
  });

  /* ---------- Notepad app ---------- */
  let tabs = [];
  let activeTabId = null;
  let tabCounter = 0;

  function saveTabs() {
    try {
      localStorage.setItem('notepad-tabs', JSON.stringify(tabs));
    } catch(e) { /* ignore */ }
  }

  function loadTabs() {
    try {
      const data = localStorage.getItem('notepad-tabs');
      if (data) {
        tabs = JSON.parse(data);
        if (tabs.length > 0) {
          activeTabId = tabs[0].id;
          renderTabs();
          updateEditor();
          return;
        }
      }
    } catch(e) { /* ignore */ }
    addTab();
  }

  function addTab() {
    tabCounter++;
    const id = 'tab-' + tabCounter;
    const tab = { id, title: 'Untitled', content: '' };
    tabs.push(tab);
    activeTabId = id;
    renderTabs();
    updateEditor();
    saveTabs();
  }

  function renderTabs() {
    const container = document.getElementById('tabs');
    const newBtn = document.getElementById('new-tab');
    container.innerHTML = '';
    container.appendChild(newBtn);
    tabs.forEach(tab => {
      const el = document.createElement('button');
      el.className = 'tab' + (tab.id === activeTabId ? ' active' : '');
      el.textContent = tab.title;
      el.addEventListener('click', () => {
        activeTabId = tab.id;
        renderTabs();
        updateEditor();
      });
      container.appendChild(el);
    });
  }

  function updateEditor() {
    const editor = document.getElementById('editor');
    const tab = tabs.find(t => t.id === activeTabId);
    editor.value = tab ? tab.content : '';
  }

  document.getElementById('new-tab').addEventListener('click', () => {
    addTab();
  });

  document.getElementById('editor').addEventListener('input', () => {
    const tab = tabs.find(t => t.id === activeTabId);
    if (tab) {
      tab.content = document.getElementById('editor').value;
      saveTabs();
    }
  });

  /* ---------- Init ---------- */
  loadTabs();
})();
</script>
</body>
</html>
